// Infinite OS Bridge server.
  // A dependency-free local HTTP + WebSocket (RFC 6455) server on 127.0.0.1:8765
  // that the "Infinite OS Bridge" browser extension connects to. Infinite AI can
  // then drive the user's real browser (navigate, click, type, fill, extract,
  // screenshot, tab management, JS) fast — reusing the user's logged-in sessions.
  //
  // The extension authenticates with a shared token stored in
  // ~/.infinite-ai/bridge-token (generated by scripts/install-extension.ps1).

  import { createServer, type Server, type IncomingMessage, type ServerResponse } from 'node:http';
  import { createHash, randomBytes } from 'node:crypto';
  import { Socket } from 'node:net';
  import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
  import { join } from 'node:path';
  import { homedir } from 'node:os';

  const WS_GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
  export const BRIDGE_DEFAULT_PORT = 8765;
  const MAX_MESSAGE_SIZE = 48 * 1024 * 1024;
  const DEFAULT_EXEC_TIMEOUT = 45_000;

  // ── MessagePack decoder (lightweight subset) ──────────────────────────────────
  function decodeMessagePack(buf: Buffer): unknown {
    let offset = 0;
    function read(): unknown {
      if (offset >= buf.length) return undefined;
      const b = buf[offset++];
      // nil
      if (b === 0xc0) return null;
      // boolean
      if (b === 0xc2) return false;
      if (b === 0xc3) return true;
      // positive fixint
      if ((b & 0x80) === 0x00) return b;
      // negative fixint
      if ((b & 0xe0) === 0xe0) return b - 0x100;
      // fixstr
      if ((b & 0xe0) === 0xa0) {
        const len = b & 0x1f;
        const str = buf.subarray(offset, offset + len).toString('utf8');
        offset += len;
        return str;
      }
      // fixarray
      if ((b & 0xf0) === 0x90) {
        const len = b & 0x0f;
        const arr = [];
        for (let i = 0; i < len; i++) arr.push(read());
        return arr;
      }
      // fixmap
      if ((b & 0xf0) === 0x80) {
        const len = b & 0x0f;
        const obj: Record<string, unknown> = {};
        for (let i = 0; i < len; i++) { const k = read(); obj[String(k)] = read(); }
        return obj;
      }
      // str 8/16/32
      if (b === 0xd9 || b === 0xda || b === 0xdb) {
        let len = 0;
        if (b === 0xd9) len = buf[offset++];
        else if (b === 0xda) { len = buf.readUInt16BE(offset); offset += 2; }
        else { len = buf.readUInt32BE(offset); offset += 4; }
        const str = buf.subarray(offset, offset + len).toString('utf8');
        offset += len;
        return str;
      }
      // array 16/32
      if (b === 0xdc || b === 0xdd) {
        let len = 0;
        if (b === 0xdc) { len = buf.readUInt16BE(offset); offset += 2; }
        else { len = buf.readUInt32BE(offset); offset += 4; }
        const arr = [];
        for (let i = 0; i < len; i++) arr.push(read());
        return arr;
      }
      // map 16/32
      if (b === 0xde || b === 0xdf) {
        let len = 0;
        if (b === 0xde) { len = buf.readUInt16BE(offset); offset += 2; }
        else { len = buf.readUInt32BE(offset); offset += 4; }
        const obj: Record<string, unknown> = {};
        for (let i = 0; i < len; i++) { const k = read(); obj[String(k)] = read(); }
        return obj;
      }
      // int 8/16/32
      if (b === 0xd0) return buf[offset++]; // int8
      if (b === 0xd1) { const v = buf.readInt16BE(offset); offset += 2; return v; }
      if (b === 0xd2) { const v = buf.readInt32BE(offset); offset += 4; return v; }
      // float 32/64
      if (b === 0xca) { const v = buf.readFloatBE(offset); offset += 4; return v; }
      if (b === 0xcb) { const v = buf.readDoubleBE(offset); offset += 8; return v; }
      // Fallback: try JSON
      try { return JSON.parse(buf.toString('utf8')); } catch { return null; }
    }
    return read();
  }

  function encodeMessagePack(obj: unknown): Buffer {
    const bytes: number[] = [];
    function write(val: unknown): void {
      if (val === null) { bytes.push(0xc0); return; }
      if (typeof val === 'boolean') { bytes.push(val ? 0xc3 : 0xc2); return; }
      if (typeof val === 'number') {
        if (Number.isInteger(val)) {
          if (val >= 0 && val <= 127) { bytes.push(val); return; }
          if (val >= -32 && val <= -1) { bytes.push(0xe0 | (val & 0x1f)); return; }
          if (val >= -32768 && val <= 32767) { bytes.push(0xd2, (val >> 8) & 0xff, val & 0xff); return; }
          if (val >= -2147483648 && val <= 2147483647) { bytes.push(0xd3, (val >> 24) & 0xff, (val >> 16) & 0xff, (val >> 8) & 0xff, val & 0xff); return; }
          bytes.push(0xcf); writeFloat64(val); return;
        }
        bytes.push(0xcb); writeFloat64(val); return;
      }
      if (typeof val === 'string') {
        const utf8 = Buffer.from(val, 'utf8');
        const len = utf8.length;
        if (len <= 31) { bytes.push(0xa0 | len); }
        else if (len <= 255) { bytes.push(0xd9, len); }
        else if (len <= 65535) { bytes.push(0xda, (len >> 8) & 0xff, len & 0xff); }
        else { bytes.push(0xdb, (len >> 24) & 0xff, (len >> 16) & 0xff, (len >> 8) & 0xff, len & 0xff); }
        bytes.push(...utf8);
        return;
      }
      if (Array.isArray(val)) {
        const len = val.length;
        if (len <= 15) { bytes.push(0x90 | len); }
        else if (len <= 65535) { bytes.push(0xdc, (len >> 8) & 0xff, len & 0xff); }
        else { bytes.push(0xdd, (len >> 24) & 0xff, (len >> 16) & 0xff, (len >> 8) & 0xff, len & 0xff); }
        for (const item of val) write(item);
        return;
      }
      if (typeof val === 'object') {
        const keys = Object.keys(val as object);
        const len = keys.length;
        if (len <= 15) { bytes.push(0x80 | len); }
        else if (len <= 65535) { bytes.push(0xde, (len >> 8) & 0xff, len & 0xff); }
        else { bytes.push(0xdf, (len >> 24) & 0xff, (len >> 16) & 0xff, (len >> 8) & 0xff, len & 0xff); }
        for (const key of keys) { write(key); write((val as Record<string, unknown>)[key]); }
        return;
      }
      // Fallback
      const json = JSON.stringify(val);
      const utf8 = Buffer.from(json, 'utf8');
      bytes.push(0xda, (utf8.length >> 8) & 0xff, utf8.length & 0xff, ...utf8);
    }
    function writeFloat64(val: number): void {
      const buf = Buffer.alloc(8);
      buf.writeDoubleBE(val, 0);
      bytes.push(...buf);
    }
    write(obj);
    return Buffer.from(bytes);
  }

  export interface BridgeStatus {
    connected: boolean;
    port: number;
    tokenConfigured: boolean;
    extensionId: string;
    extensionVersion: string;
    browser: string;
    name: string;
    lastError: string;
    connectedAt: number | null;
    commandsServed: number;
  }

  type ExecResult = { ok: true; data: unknown } | { ok: false; error: string };

  // ---------------------------------------------------------------------------
  // Minimal WebSocket connection (server side)
  // ---------------------------------------------------------------------------

  class WsConnection {
    private socket: Socket;
    private buffer: Buffer = Buffer.alloc(0);
    private messageParts: Buffer[] = [];
    private messageOpcode = 0;
    private fragmented = false;
    private closed = false;
    private useBinary = false;

    onMessage: ((data: string) => void) | null = null;
    onClose: (() => void) | null = null;

    constructor(socket: Socket) {
      this.socket = socket;
      socket.on('data', (chunk) => this.handleData(chunk));
      socket.on('close', () => {
        this.closed = true;
        this.onClose?.();
      });
      socket.on('error', () => {
        this.closed = true;
        this.onClose?.();
      });
    }

    private handleData(chunk: Buffer): void {
      this.buffer = this.buffer.length ? Buffer.concat([this.buffer, chunk]) : chunk;
      this.buffer = this.parseFrames(this.buffer);
    }

    private parseFrames(data: Buffer): Buffer {
      let offset = 0;
      while (data.length - offset >= 2) {
        const b0 = data[offset];
        const b1 = data[offset + 1];
        const fin = (b0 & 0x80) !== 0;
        const opcode = b0 & 0x0f;
        const masked = (b1 & 0x80) !== 0;
        let len = b1 & 0x7f;
        let headerLen = 2;

        if (len === 126) {
          if (data.length - offset < 4) break;
          len = data.readUInt16BE(offset + 2);
          headerLen = 4;
        } else if (len === 127) {
          if (data.length - offset < 10) break;
          const high = data.readUInt32BE(offset + 2);
          const low = data.readUInt32BE(offset + 6);
          len = high * 0x100000000 + low;
          headerLen = 10;
        }

        let maskKey: Buffer | null = null;
        if (masked) {
          if (data.length - offset < headerLen + 4) break;
          maskKey = data.subarray(offset + headerLen, offset + headerLen + 4);
          headerLen += 4;
        }

        if (len > MAX_MESSAGE_SIZE) {
          this.closeWithCode(1009, 'message too large');
          return data;
        }

        if (data.length - offset < headerLen + len) break;

        const payloadStart = offset + headerLen;
        const payload = Buffer.from(data.subarray(payloadStart, payloadStart + len));
        if (maskKey) {
          for (let i = 0; i < payload.length; i++) payload[i] ^= maskKey[i % 4];
        }
        offset = payloadStart + len;

        if (opcode === 0x8) {
          this.closeWithCode(1000, '');
          return data.subarray(offset);
        }
        if (opcode === 0x9) {
          this.sendFrame(0xa, payload);
          continue;
        }
        if (opcode === 0xa) continue;

        if (opcode === 0x1 || opcode === 0x2) {
          this.fragmented = !fin;
          this.messageOpcode = opcode;
          this.messageParts = [payload];
        } else if (opcode === 0x0) {
          if (!this.fragmented) {
            this.closeWithCode(1002, 'unexpected continuation');
            return data.subarray(offset);
          }
          this.messageParts.push(payload);
          if (fin) {
            this.fragmented = false;
            const full = Buffer.concat(this.messageParts);
            this.deliver(full);
          }
        } else {
          this.closeWithCode(1003, 'unsupported opcode');
          return data.subarray(offset);
        }

        if (fin && (opcode === 0x1 || opcode === 0x2)) {
          this.deliver(payload);
        }
      }
      return data.subarray(offset);
    }

    private deliver(payload: Buffer): void {
      let msg: unknown;
      if (this.useBinary) {
        try { msg = decodeMessagePack(payload); } catch { return; }
      } else {
        if (this.messageOpcode !== 0x1) return;
        try { msg = JSON.parse(payload.toString('utf8')); } catch { return; }
      }

      if (!msg || typeof msg !== 'object') return;
      const m = msg as { type?: string; binary?: boolean; id?: string | number; ok?: boolean; data?: unknown; error?: string; time?: number };

      if (m.type === 'hello') {
        this.useBinary = m.binary === true;
        if (this.useBinary) {
          this.sendFrame(0x2, encodeMessagePack({ type: 'binary-ack' }));
        }
        this.onMessage?.(JSON.stringify(msg));
        return;
      }

      // Convert MessagePack objects to JSON string for existing handler
      if (this.onMessage) {
        if (this.useBinary) {
          this.onMessage(JSON.stringify(msg));
        } else {
          this.onMessage(payload.toString('utf8'));
        }
      }
    }

    private sendFrame(opcode: number, payload: Buffer): void {
      if (this.closed) return;
      const len = payload.length;
      let header: Buffer;
      if (len <= 125) {
        header = Buffer.from([0x80 | opcode, len]);
      } else if (len <= 0xffff) {
        header = Buffer.alloc(4);
        header[0] = 0x80 | opcode;
        header[1] = 126;
        header.writeUInt16BE(len, 2);
      } else {
        header = Buffer.alloc(10);
        header[0] = 0x80 | opcode;
        header[1] = 127;
        header.writeUInt32BE(Math.floor(len / 0x100000000), 2);
        header.writeUInt32BE(len % 0x100000000, 6);
      }
      try {
        this.socket.write(Buffer.concat([header, payload]));
      } catch {
        /* socket may be gone */
      }
    }

    sendText(text: string): void {
      if (this.useBinary) {
        this.sendFrame(0x2, encodeMessagePack(JSON.parse(text)));
      } else {
        this.sendFrame(0x1, Buffer.from(text, 'utf8'));
      }
    }

    private closeWithCode(code: number, reason: string): void {
      if (this.closed) return;
      this.closed = true;
      const payload = Buffer.alloc(2 + Buffer.byteLength(reason, 'utf8'));
      payload.writeUInt16BE(code, 0);
      payload.write(reason, 2, 'utf8');
      try {
        this.sendFrame(0x8, payload);
      } catch {
        /* ignore */
      }
      this.socket.end();
    }

    close(): void {
      this.closeWithCode(1000, '');
    }
  }

// ---------------------------------------------------------------------------
// Bridge server
// ---------------------------------------------------------------------------

class BridgeServer {
  private server: Server | null = null;
  private ws: WsConnection | null = null;
  private token = '';
  private pending = new Map<string, { resolve: (r: ExecResult) => void; timer: NodeJS.Timeout }>();
  private nextId = 1;
  private commandsServed = 0;
  private inFlight = new Map<string, { promise: Promise<ExecResult>; expires: number }>();
  private readonly COALESCE_WINDOW_MS = 16;
  readonly port: number;

  status: BridgeStatus = {
    connected: false,
    port: BRIDGE_DEFAULT_PORT,
    tokenConfigured: false,
    extensionId: '',
    extensionVersion: '',
    browser: '',
    name: '',
    lastError: '',
    connectedAt: null,
    commandsServed: 0,
  };

  constructor(port = BRIDGE_DEFAULT_PORT) {
    this.port = port;
    this.status.port = port;
  }

  private tokenPath(): string {
    return join(homedir(), '.infinite-ai', 'bridge-token');
  }

  private loadOrCreateToken(): string {
    const path = this.tokenPath();
    try {
      if (existsSync(path)) {
        const existing = readFileSync(path, 'utf8').trim();
        if (existing) {
          this.token = existing;
          return existing;
        }
      }
      mkdirSync(join(homedir(), '.infinite-ai'), { recursive: true });
      const fresh = randomBytes(32).toString('base64url');
      writeFileSync(path, fresh, { encoding: 'utf8', flag: 'w' });
      this.token = fresh;
      return fresh;
    } catch {
      this.token = '';
      return '';
    }
  }

  private tokensMatch(provided: string | undefined | null): boolean {
    // If the token file could not be read/generated, reject all connections
    // rather than silently disabling authentication.
    if (!this.token) return false;
    if (!provided) return false;
    const a = Buffer.from(provided);
    const b = Buffer.from(this.token);
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
    return diff === 0;
  }

  private requestToken(req: IncomingMessage): string {
    const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
    const fromQuery = url.searchParams.get('token') || '';
    if (fromQuery) return fromQuery;
    const header = req.headers['x-bridge-token'];
    if (typeof header === 'string' && header) return header;
    const auth = req.headers['authorization'];
    if (typeof auth === 'string' && auth.startsWith('Bearer ')) return auth.slice(7);
    return '';
  }

  private sendJson(res: ServerResponse, code: number, body: unknown): void {
    const data = JSON.stringify(body);
    res.writeHead(code, {
      'content-type': 'application/json; charset=utf-8',
      'content-length': Buffer.byteLength(data),
      'cache-control': 'no-store',
      'access-control-allow-origin': '*',
    });
    res.end(data);
  }

  private setConnected(ws: WsConnection, info: { extensionId?: string; version?: string; browser?: string; name?: string }): void {
    if (this.ws && this.ws !== ws) {
      try {
        this.ws.close();
      } catch {
        /* ignore */
      }
    }
    this.ws = ws;
    this.status.connected = true;
    this.status.extensionId = info.extensionId || '';
    this.status.extensionVersion = info.version || '';
    this.status.browser = info.browser || '';
    this.status.name = info.name || '';
    this.status.lastError = '';
    this.status.connectedAt = Date.now();
    this.log(`Extension connected (${this.status.extensionId || 'unknown id'})`);
    ws.onMessage = (data) => this.handleExtensionMessage(data);
    ws.onClose = () => {
      if (this.ws === ws) {
        this.ws = null;
        this.status.connected = false;
        this.status.lastError = 'extension disconnected';
        this.log('Extension disconnected');
        this.rejectAllPending(new Error('Browser bridge disconnected while a command was running'));
      }
    };
  }

  private handleExtensionMessage(data: string): void {
    let msg: unknown;
    try {
      msg = JSON.parse(data);
    } catch {
      return;
    }
    if (!msg || typeof msg !== 'object') return;
    const m = msg as { type?: string; id?: string | number; ok?: boolean; data?: unknown; error?: string; time?: number };
    if (m.type === 'hello') {
      this.setConnected(this.ws as WsConnection, {
        extensionId: (msg as { extensionId?: string }).extensionId,
        version: (msg as { version?: string }).version,
        browser: (msg as { browser?: string }).browser,
        name: (msg as { name?: string }).name,
      });
      return;
    }
    if (m.type === 'pong-server') return;
    if (m.type === 'ping-server') {
      this.ws?.sendText(JSON.stringify({ type: 'pong-server', time: Date.now() }));
      return;
    }
    if (m.id != null) {
      const pending = this.pending.get(String(m.id));
      if (pending) {
        clearTimeout(pending.timer);
        this.pending.delete(String(m.id));
        if (m.ok === true) pending.resolve({ ok: true, data: m.data });
        else pending.resolve({ ok: false, error: String(m.error || 'Unknown bridge error') });
      }
    }
  }

  private rejectAllPending(err: Error): void {
    for (const [, p] of this.pending) {
      clearTimeout(p.timer);
      p.resolve({ ok: false, error: err.message });
    }
    this.pending.clear();
  }

  exec(command: string, params?: Record<string, unknown>, timeoutMs = DEFAULT_EXEC_TIMEOUT): Promise<ExecResult> {
    if (!this.ws || !this.status.connected) {
      return Promise.resolve({
        ok: false,
        error:
          'Browser bridge not connected. The Infinite OS Bridge extension is not linked to Infinite OS. DO NOT open a new Chrome window. Instead, tell the user: "The browser extension is not connected. Please go to chrome://extensions, find Infinite OS Bridge, and click the reload button. Then I can use your existing browser." Wait for the user to fix it, then retry.',
      });
    }

    // Request coalescing: deduplicate identical commands within COALESCE_WINDOW_MS
    const coalesceKey = command + ':' + JSON.stringify(params || {});
    const now = Date.now();
    const existing = this.inFlight.get(coalesceKey);
    if (existing && existing.expires > now) {
      return existing.promise;
    }

    const id = String(this.nextId++);
    const payload = { id, command, params: params || {} };
    const promise = new Promise<ExecResult>((resolve) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        this.inFlight.delete(coalesceKey);
        resolve({ ok: false, error: `Bridge command "${command}" timed out after ${timeoutMs}ms` });
      }, timeoutMs);
      this.pending.set(id, { resolve, timer });
    });

    this.inFlight.set(coalesceKey, { promise, expires: now + this.COALESCE_WINDOW_MS });

    try {
      this.ws.sendText(JSON.stringify(payload));
    } catch (err) {
      this.pending.delete(id);
      this.inFlight.delete(coalesceKey);
      return Promise.resolve({ ok: false, error: String((err as Error).message || err) });
    }
    return promise.then((result) => {
      this.inFlight.delete(coalesceKey);
      if (result.ok) this.commandsServed++;
      this.status.commandsServed = this.commandsServed;
      return result;
    });
  }

  getStatus(): BridgeStatus {
    return { ...this.status };
  }

  /**
   * Auto-sync the bridge token to all extension config.js files so the
   * extension can always authenticate. This fixes the common issue where
   * the source config.js has a stale hardcoded token.
   */
  private syncTokenToExtensions(): void {
    if (!this.token) return;
    const configContent = `const BRIDGE_CONFIG = { port: ${this.port}, token: "${this.token}" };\n`;
    // Source extension directory
    const sourceDir = join(process.cwd(), 'extensions', 'infinite-os-bridge');
    // Installed extension directory
    const installedDir = join(homedir(), '.infinite-ai', 'extensions', 'infinite-os-bridge');
    for (const dir of [sourceDir, installedDir]) {
      try {
        const configPath = join(dir, 'config.js');
        mkdirSync(dir, { recursive: true });
        writeFileSync(configPath, configContent, { encoding: 'utf8', flag: 'w' });
      } catch {
        // Non-fatal: extension may not be installed yet
      }
    }
  }

  private handleUpgrade(req: IncomingMessage, socket: Socket, head: Buffer): void {
    const token = this.requestToken(req);
    if (!this.tokensMatch(token)) {
      socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
      socket.destroy();
      return;
    }
    const key = req.headers['sec-websocket-key'];
    if (!key) {
      socket.write('HTTP/1.1 400 Bad Request\r\n\r\n');
      socket.destroy();
      return;
    }
    const accept = createHash('sha1').update(key + WS_GUID).digest('base64');
    socket.write(
      'HTTP/1.1 101 Switching Protocols\r\n' +
        'Upgrade: websocket\r\n' +
        'Connection: Upgrade\r\n' +
        `Sec-WebSocket-Accept: ${accept}\r\n\r\n`,
    );
    if (head && head.length) socket.unshift(head);
    const conn = new WsConnection(socket);
    this.setConnected(conn, {});
  }

  start(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.loadOrCreateToken();
      this.status.tokenConfigured = Boolean(this.token);
      this.syncTokenToExtensions();
      const server = createServer((req, res) => {
        void this.handleHttp(req, res);
      });
      server.on('upgrade', (req, socket, head) => {
        if (req.url?.startsWith('/bridge')) {
          this.handleUpgrade(req, socket as Socket, head as Buffer);
        } else {
          socket.destroy();
        }
      });
      server.on('error', (err: NodeJS.ErrnoException) => {
        if (err.code === 'EADDRINUSE') {
          this.log(`Port ${this.port} already in use — another bridge instance (e.g. the Infinite OS app) is running.`);
          resolve();
          return;
        }
        reject(err);
      });
      server.listen(this.port, '127.0.0.1', () => {
        this.server = server;
        this.log(`Bridge server listening on ws://127.0.0.1:${this.port} (token ${this.status.tokenConfigured ? 'set' : 'unset'})`);
        resolve();
      });
    });
  }

  private async handleHttp(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
    const path = url.pathname;

    if (path === '/healthz') {
      this.sendJson(res, 200, { ok: true, ts: Date.now() });
      return;
    }

    if (path === '/status') {
      if (!this.tokensMatch(this.requestToken(req))) {
        this.sendJson(res, 401, { ok: false, error: 'unauthorized' });
        return;
      }
      this.sendJson(res, 200, { ok: true, status: this.getStatus() });
      return;
    }

    if (path === '/exec' && req.method === 'POST') {
      if (!this.tokensMatch(this.requestToken(req))) {
        this.sendJson(res, 401, { ok: false, error: 'unauthorized' });
        return;
      }
      let body = '';
      for await (const chunk of req) {
        body += chunk;
        if (body.length > 1024 * 1024) break;
      }
      let parsed: { command?: string; params?: Record<string, unknown>; timeoutMs?: number };
      try {
        parsed = JSON.parse(body || '{}');
      } catch {
        this.sendJson(res, 400, { ok: false, error: 'invalid JSON body' });
        return;
      }
      if (!parsed.command) {
        this.sendJson(res, 400, { ok: false, error: 'missing "command"' });
        return;
      }
      const result = await this.exec(parsed.command, parsed.params || {}, parsed.timeoutMs || DEFAULT_EXEC_TIMEOUT);
      const respBody = result.ok ? { ok: true, data: result.data } : { ok: false, error: result.error };
      this.sendJson(res, result.ok ? 200 : 502, respBody);
      return;
    }

    this.sendJson(res, 404, { ok: false, error: 'not found' });
  }

  stop(): void {
    this.rejectAllPending(new Error('Bridge server stopped'));
    if (this.ws) {
      try {
        this.ws.close();
      } catch {
        /* ignore */
      }
      this.ws = null;
    }
    this.status.connected = false;
    if (this.server) {
      this.server.close();
      this.server = null;
    }
  }

  private log(message: string): void {
    console.log(`[bridge] ${message}`);
  }
}

export { BridgeServer };
export const bridgeServer = new BridgeServer();
